script:
persist.table "T" { k = "string:key", v = "number" }
on_start(function()
  task.spawn(function()
    local ok, err = pcall(function()
      txn(function() T.upsert{ k = "x", v = 1 } time.sleep(10) T.upsert{ k = "y", v = 2 } end)
    end)
    log.info("txn err=%s", ok and "none" or err.kind)
  end)
end)
